param([Parameter(Mandatory)][string]$OutputPath)
$ErrorActionPreference='Stop';Set-StrictMode -Version Latest
$coreHash=(Get-FileHash -LiteralPath ([object].Assembly.Location) -Algorithm SHA256).Hash.ToLowerInvariant();if([Environment]::Version.ToString() -ne '10.0.12' -or $coreHash -ne '1125acc8106c43fc8bad2d203c4c4485df6182d292846c2fff415c1040c54678'){throw 'Pinned CoreLib required'}
function Failure-Of($ErrorRecord){$e=$ErrorRecord.Exception;while($e.InnerException){$e=$e.InnerException};$r=[ordered]@{ok=$false;exception=$e.GetType().FullName;message=$e.Message;hResult=$e.HResult;paramName=$(if($e -is [ArgumentException]){$e.ParamName}else{$null})};if($e -is [Text.EncoderFallbackException]){$r.unknown=[int]$e.CharUnknown;$r.index=$e.Index;$r.high=[int]$e.CharUnknownHigh;$r.low=[int]$e.CharUnknownLow;$r.isPair=$e.IsUnknownSurrogate()};if($e -is [Text.DecoderFallbackException]){$r.bytesUnknown=[int[]]$e.BytesUnknown;$r.index=$e.Index};return $r}

function Bridge([string]$Direction,[bool]$Write){
 $encoder=$Direction -eq 'Encoder';$owner=[Text.Encoding];$sourceElement=if($encoder){[char]}else{[byte]};$destinationElement=if($encoder){[byte]}else{[char]};$sourceArray=$sourceElement.MakeArrayType();$destinationArray=$destinationElement.MakeArrayType();$readOnly=[type]'System.ReadOnlySpan`1';$span=[type]'System.Span`1';$sourceType=$readOnly.MakeGenericType([type[]]@($sourceElement));$destinationType=$span.MakeGenericType([type[]]@($destinationElement))
 [type[]]$signature=if($Write){@($owner,$sourceArray,[int],[int],$destinationArray,[int],[int],[int[]])}else{@($owner,$sourceArray,[int],[int])};$methodName=if($encoder){if($Write){'TryGetBytes'}else{'GetByteCount'}}else{if($Write){'TryGetChars'}else{'GetCharCount'}};[type[]]$methodSignature=if($Write){@($sourceType,$destinationType,[int].MakeByRefType())}else{@($sourceType)};$method=$owner.GetMethod($methodName,$methodSignature)
 $bridge=[Reflection.Emit.DynamicMethod]::new('EncodingTry'+$Direction+$Write,[bool],$signature);$il=$bridge.GetILGenerator();$il.Emit([Reflection.Emit.OpCodes]::Ldarg_0);$il.Emit([Reflection.Emit.OpCodes]::Ldarg_1);$il.Emit([Reflection.Emit.OpCodes]::Ldarg_2);$il.Emit([Reflection.Emit.OpCodes]::Ldarg_3);$il.Emit([Reflection.Emit.OpCodes]::Newobj,$sourceType.GetConstructor([type[]]@($sourceArray,[int],[int])))
 if($Write){$il.Emit([Reflection.Emit.OpCodes]::Ldarg_S,[byte]4);$il.Emit([Reflection.Emit.OpCodes]::Ldarg_S,[byte]5);$il.Emit([Reflection.Emit.OpCodes]::Ldarg_S,[byte]6);$il.Emit([Reflection.Emit.OpCodes]::Newobj,$destinationType.GetConstructor([type[]]@($destinationArray,[int],[int])))};$il.Emit([Reflection.Emit.OpCodes]::Ldarg_S,[byte]7);$il.Emit([Reflection.Emit.OpCodes]::Ldc_I4_0);$il.Emit([Reflection.Emit.OpCodes]::Ldelema,[int]);$il.Emit([Reflection.Emit.OpCodes]::Callvirt,$method);$il.Emit([Reflection.Emit.OpCodes]::Ret);$definition=[type]('System.Func`'+($signature.Count+1));return $bridge.CreateDelegate($definition.MakeGenericType([type[]]@($signature+[bool])))
}

$tryBridge=Bridge 'Decoder' $true
$replacements=@(@(),@(0),@(65,0),@(0,66),@(65,0,66),@(55296,56320),@(65,0,55296,56320),@(55296,56320,0,65),@(0,55296,56320,0));$inputs=@(@(),@(65),@(0),@(255),@(0,65),@(65,0),@(0,216),@(216,0),@(0,220),@(220,0),@(0,216,0,220),@(216,0,220,0),@(0,216,65,0),@(216,0,0,65),@(0,216,255),@(216,0,255),@(0,216,0,216,255));$profiles=[Collections.Generic.List[object]]::new()
foreach($big in @($false,$true)){foreach($replacement in $replacements){$owner=[Text.Encoding]([Text.UnicodeEncoding]::new($big,$true,$false)).Clone();$owner.DecoderFallback=[Text.DecoderReplacementFallback]::new([string]::new([char[]][int[]]$replacement));$rows=[Collections.Generic.List[object]]::new()
 foreach($units in $inputs){$source=[byte[]](@(221)+$units+@(216));$views=@(@(1,$units.Length),@(($units.Length+1),0));if($units.Length){$views+=,@($units.Length,1)};$seen=[Collections.Generic.HashSet[string]]::new();foreach($view in $views){$start=[int]$view[0];$count=[int]$view[1];if(-not $seen.Add("$start,$count")){continue};$visible=[byte[]]::new($count);[Array]::Copy($source,$start,$visible,0,$count);foreach($capacity in @(0,1,2,3,4,8)){foreach($offset in @(0,2)){$dest=[char[]](@(99)*($offset+$capacity+3));$written=[int[]]@(-7);$a=[object[]]::new(8);$a[0]=$owner;$a[1]=$source;$a[2]=$start;$a[3]=$count;$a[4]=$dest;$a[5]=$offset;$a[6]=$capacity;$a[7]=$written;try{$success=$tryBridge.DynamicInvoke($a);$result=[ordered]@{ok=$true;success=[bool]$success}}catch{$result=Failure-Of $_};$required=$owner.GetCharCount($source,$start,$count)
  $rows.Add([ordered]@{source=[int[]]$source;start=$start;count=$count;capacity=$capacity;offset=$offset;required=$required;result=$result;written=$written[0];after=[int[]]$dest})
 }}
 }};$profiles.Add([ordered]@{bigEndian=$big;replacement=[int[]]$replacement;rows=$rows.ToArray()})
}}

$record=[ordered]@{schemaVersion=1;runtimeVersion=[Environment]::Version.ToString();coreLibSha256=$coreHash;oracleSha256=(Get-FileHash -LiteralPath $PSCommandPath -Algorithm SHA256).Hash.ToLowerInvariant();profiles=$profiles.ToArray();qualification='NATIVE_STATELESS_UNICODE_DECODER_REPLACEMENT_TRY_HEAP_SPANS_ONLY; NO_JAVA_QUALIFICATION_OR_TASK_ACCEPTANCE'}
[IO.File]::WriteAllText($OutputPath,($record|ConvertTo-Json -Depth 19 -Compress)+"`n",[Text.UTF8Encoding]::new($false));Write-Output "PASS decoder replacement Try span capture: $($profiles.Count) configurations"
